/**
 * Build-time access to the commentary data (content/commentary/, generated by scripts/commentary).
 *
 * For each chapter the reader offers, in order of preference:
 *  1. the St. Mark Church commentary text, verse by verse (Arabic);
 *  2. the St. Mark PDF, where a book has no extractable text (Job, Esther);
 *  3. Fr. Tadros Malaty's commentary on St-Takla.org, linked, for books St. Mark does not cover.
 */
import { existsSync, readFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import type { CommentaryBook, CommentaryChapter } from '@orthodoxia/commentary';

const CONTENT = resolve(process.cwd(), '../../content/commentary');

const stMarkCache = new Map<string, CommentaryBook | null>();
function stMarkBook(code: string): CommentaryBook | null {
  if (!stMarkCache.has(code)) {
    const path = join(CONTENT, 'stmark', `${code}.json`);
    stMarkCache.set(code, existsSync(path) ? (JSON.parse(readFileSync(path, 'utf8')) as CommentaryBook) : null);
  }
  return stMarkCache.get(code) ?? null;
}

interface MalatyLinks {
  readonly books: Record<string, { index: string; chapters: Record<string, string> }>;
}
let malaty: MalatyLinks | undefined;
function malatyLinks(): MalatyLinks {
  malaty ??= JSON.parse(readFileSync(join(CONTENT, 'malaty', 'links.json'), 'utf8')) as MalatyLinks;
  return malaty;
}

/**
 * Where a canonical book/chapter sits in Malaty's commentary, which follows the Greek-inclusive
 * numbering: Esther's additions are Esther 11–16, the Song of the Three is in Daniel 3, Susanna and
 * Bel are Daniel 13 and 14.
 */
function malatyLocation(book: string, chapter: number): [string, number] {
  if (book === 'ESG') return ['EST', chapter];
  if (book === 'S3Y') return ['DAN', 3];
  if (book === 'SUS') return ['DAN', 13];
  if (book === 'BEL') return ['DAN', 14];
  return [book, chapter];
}

export interface ChapterCommentary {
  /** St. Mark text for this chapter, with what the reader must know about it. */
  readonly stMark: {
    readonly chapter: CommentaryChapter;
    readonly repaired: boolean;
    /** The PDF the chapter comes from, to read it in the original. */
    readonly documentUrl: string;
  } | null;
  /** The St. Mark PDF for books whose text could not be extracted. */
  readonly stMarkPdf: string | null;
  /** Fr. Tadros Malaty's chapter page on St-Takla.org. */
  readonly malatyUrl: string | null;
}

export function chapterCommentary(book: string, chapter: number): ChapterCommentary {
  const stMark = stMarkBook(book);
  let text: ChapterCommentary['stMark'] = null;
  let pdf: string | null = null;
  if (stMark !== null) {
    const found = stMark.chapters.find((candidate) => candidate.chapter === chapter);
    const document = stMark.documents.find(({ chapters: [first, last] }) => chapter >= first && chapter <= last) ?? stMark.documents[0];
    if (found !== undefined && found.entries.length > 0 && document !== undefined) {
      text = { chapter: found, repaired: stMark.extraction === 'pdf-text-repaired', documentUrl: document.url };
    } else if (stMark.extraction === 'pdf-link' && document !== undefined) {
      pdf = document.url;
    }
  }
  const [malatyBook, malatyChapter] = malatyLocation(book, chapter);
  const links = malatyLinks().books[malatyBook];
  const malatyUrl = links?.chapters[String(malatyChapter)] ?? null;
  return { stMark: text, stMarkPdf: pdf, malatyUrl };
}

/** Whether any commentary is available for a chapter. */
export function hasCommentary(commentary: ChapterCommentary): boolean {
  return commentary.stMark !== null || commentary.stMarkPdf !== null || commentary.malatyUrl !== null;
}
